import{_ as o,a0 as p,w as r,s as d,I as n,x as i,a1 as t,A as a,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"NixOS Linux： 先配置後安裝的 Linux | LCTT x X-CMD","titleTemplate":false,"description":"NixOS Linux： 先配置後安裝的 Linux | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NixOS Linux： 先配置後安裝的 Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NixOS Linux： 先配置後安裝的 Linux | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20171013 NixOS Linux Lets You Configure Your OS Before Installing","title":"NixOS Linux： 先配置後安裝的 Linux","tag":"201710","desc":""},"relativePath":"201710/20171013 NixOS Linux Lets You Configure Your OS Before Installing.md","filePath":"[post].md"}'),u={name:"201710/20171013 NixOS Linux Lets You Configure Your OS Before Installing.md"};function g(x,s,k,h,f,m){const e=p("Link");return r(),d("div",null,[s[30]||(s[30]=n("h1",{id:"nixos-linux-先配置後安裝的-linux",tabindex:"-1"},[i("NixOS Linux： 先配置後安裝的 Linux "),n("a",{class:"header-anchor",href:"#nixos-linux-先配置後安裝的-linux","aria-label":"Permalink to “NixOS Linux： 先配置後安裝的 Linux”"},"​")],-1)),s[31]||(s[31]=n("p",null,[n("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/configuration.jpg?itok=IjKuFz05",alt:"NixOS",title:"NixOS"})],-1)),s[32]||(s[32]=n("p",null,"配置是成功安裝 NixOS 的關鍵。",-1)),s[33]||(s[33]=n("p",null,"我用 Linux 有些年頭了。在這些年裏我很有幸見證了開源的發展。各色各樣的發行版在安裝方面的努力，也是其中的一個比較獨特的部分。以前，安裝 Linux 是個最好讓有技術的人來乾的任務。現在，只要你會裝軟件，你就會安裝 Linux。簡單，並且，不是我吹，在吸引新用户方面效果拔羣。事實上安裝整個 Linux 操作系統都要比 Windows 用户安裝個更新看起來要快一點。",-1)),n("p",null,[s[1]||(s[1]=i("但每一次，我都喜歡看到一些不同的東西——那些可以讓我體驗新鮮的東西。",-1)),t(e,{href:"https://nixos.org/"},{default:a(()=>[...s[0]||(s[0]=[i("NixOS",-1)])]),_:1}),s[2]||(s[2]=i(" 在這方面就做的別具一格。講真，我原來也就把它當作另一個提供標準特性和 KDE Plasma 5 界面的 Linux 發行版。",-1))]),s[34]||(s[34]=n("p",null,"好像也沒什麼不對。",-1)),n("p",null,[t(e,{href:"https://nixos.org/nixos/download.html"},{default:a(()=>[...s[3]||(s[3]=[i("下載 ISO 映像",-1)])]),_:1}),s[5]||(s[5]=i("後，我啓動了 ",-1)),t(e,{href:"https://www.virtualbox.org/wiki/Downloads"},{default:a(()=>[...s[4]||(s[4]=[i("VirtualBox",-1)])]),_:1}),s[6]||(s[6]=i(" 並用下載的鏡像創建了個新的虛擬機。VM 啓動後，出來的是 Bash 的登錄界面，界面上指導我用空密碼去登錄 root 賬號，以及我該如何啓動 GUI 顯示管理器（圖 1）。",-1))]),s[35]||(s[35]=l(`<p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/nixos_1.jpg?itok=VkGTO2Tg" alt="First contact" title="First contact"></p><p><em>圖 1： 與 NixOS 的初次接觸可能不是太和諧。</em></p><p>“好吧”我這樣想着，“打開看看吧！”</p><p>GUI 啓動和運行時（KDE Plasma 5），我沒找到喜聞樂見的“安裝”按鈕。原來，NixOS 是一個在安裝前需要你配置的發行版，真有趣。那就讓我們瞧瞧它是如何做到的吧！</p><h3 id="安裝前配置" tabindex="-1">安裝前配置 <a class="header-anchor" href="#安裝前配置" aria-label="Permalink to “安裝前配置”">​</a></h3><p>你需要做的第一件事是建分區。由於 NixOS 安裝程序不包含分區工具，你得用自帶的 GParted （圖 2）來創建一個 EXT4 分區。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/nixos_2.jpg?itok=nta-bl-S" alt="Partitioning" title="Partitioning"></p><p><em>圖 2： 安裝前對磁盤分區。</em></p><p>創建好分區，然後用命令 <code>mount /dev/sdX /mnt</code> 掛載。（請自行替換 <code>sdX</code> 為你新創建的分區）。</p><p>你現在需要創建一個配置文件。命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nixos-generate-config --root /mnt</span></span></code></pre></div><p>上面的命令會創建兩個文件（存放在目錄 <code>/mnt/etc/nixos</code> 中）：</p><ul><li><code>configuration.nix</code> — 默認配置文件。</li><li><code>hardware-configuration.nix</code> — 硬件配置（無法編輯）</li></ul><p>通過命令 <code>nano /mnt/etc/nixos/configuration.nix</code> 打開文件。其中有一些需要編輯的地方得注意。第一個改動便是設置啓動選項。找到行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># boot.loader.grub.device = &quot;/dev/sda&quot;; # 或 efi 時用 &quot;nodev&quot;</span></span></code></pre></div><p>刪除行首的 <code>#</code> 使該選項生效（確保 <code>/dev/sda</code> 與你新建的分區）。</p><p>通過配置文件，你可以設置時區和追加要安裝的軟件包。來看一個被註釋掉的安裝包的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># List packages installed in system profile. To search by name, run:</span></span>
<span class="line"><span># nix-env -aqP | grep wget</span></span>
<span class="line"><span># environment.systemPackages = with pkgs; [</span></span>
<span class="line"><span>#     wget vim</span></span>
<span class="line"><span># ];</span></span></code></pre></div><p>如果你想要添加軟件包，並在安裝時安裝它們，那就取消掉這段註釋，並添加你需要的軟件包。舉個例子，比方説你要把 LibreOffice 加進去。示例詳見下方：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># List packages installed in system profile. To search by name, run:</span></span>
<span class="line"><span>nix-env -aqP | grep wget</span></span>
<span class="line"><span>environment.systemPackages = with pkgs; [</span></span>
<span class="line"><span>    libreoffice wget vim</span></span>
<span class="line"><span>];</span></span></code></pre></div>`,20)),n("p",null,[s[8]||(s[8]=i("你可以通過輸入命令 ",-1)),s[9]||(s[9]=n("code",null,"nix-env -aqP | grep PACKAGENAME",-1)),s[10]||(s[10]=i(" 來尋找確切的包名（",-1)),s[11]||(s[11]=n("code",null,"PACKAGENAME",-1)),s[12]||(s[12]=i(" 為你想要找的軟件包）。如果你不想輸命令，你也可以檢索 ",-1)),t(e,{href:"https://nixos.org/nixos/packages.html"},{default:a(()=>[...s[7]||(s[7]=[i("NixOS 的軟件包資料庫",-1)])]),_:1}),s[13]||(s[13]=i("。",-1))]),s[36]||(s[36]=l(`<p>在你把所有的軟件包都添加完後，你還有件事兒需要做（如果你想要登錄到桌面的話，我覺得你還得折騰下 KDE Plasma 5 桌面）。翻到配置文件的末尾並在最後的 <code>}</code> 符號前，追加如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>services.xserver = {</span></span>
<span class="line"><span> enable = true;</span></span>
<span class="line"><span> displayManager.sddm.enable = true;</span></span>
<span class="line"><span> desktopManager.plasma5.enable = true;</span></span>
<span class="line"><span>};</span></span></code></pre></div>`,2)),n("p",null,[s[15]||(s[15]=i("在 ",-1)),t(e,{href:"https://nixos.org/nixos/manual/index.html#ch-configuration"},{default:a(()=>[...s[14]||(s[14]=[i("NixOS 官方文件",-1)])]),_:1}),s[16]||(s[16]=i(" 中，你能找到配置文件中更多的選項。保存並關掉配置文件。",-1))]),s[37]||(s[37]=l('<h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>在你按照自己的需求完善好配置之後，使用命令（需要 root 權限） <code>nixos-install</code>。完成安裝所需要的時間，會隨着你加入的軟件包多少有所區別。安裝結束後，你可以使用命令重啓系統，（重啓之後）迎接你的就是 KDE Plasma 5 的登錄管理界面了（圖 3）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/nixos_3.jpg?itok=DdsB5opR" alt="KDE Plasma 5" title="KDE Plasma 5"></p><p><em>圖 3： KDE Plasma 5 登錄管理界面</em></p><h3 id="安裝後" tabindex="-1">安裝後 <a class="header-anchor" href="#安裝後" aria-label="Permalink to “安裝後”">​</a></h3><p>你要首先要做的兩件事之一便是給 root 用户設個密碼（通過輸入命令 <code>passwd</code> 來修改默認的密碼），以及添加一個標準用户。做法和其它的 Linux 發行版無二。用 root 用户登錄，然後在終端輸入命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>useradd -m USER</span></span></code></pre></div><p>將 <code>USER</code> 替換成你想要添加的用户名。然後通過下面的命令給用户設上密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>passwd USER</span></span></code></pre></div><p>同樣的將 <code>USER</code> 替換成你添加的用户。</p><p>然後會有提示引導你填寫並驗證新密碼。然後，你就能用標準用户登錄 NixOS 啦。</p><p>NixOS 在你安裝並運行後，你可以為系統添加新的軟件包，但並非通過尋常的方式。如果你發現你需要安裝些新東西，你得回到配置文件（位置就是 <code>/etc/nixos/</code> ），找到之前安裝時添加軟件包的位置，運行以下命令（需要 root 權限）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nixos-rebuild switch</span></span></code></pre></div><p>命令執行結束後，你就能使用新安裝的軟件包了。</p><h3 id="enjoy-nixos" tabindex="-1">Enjoy NixOS <a class="header-anchor" href="#enjoy-nixos" aria-label="Permalink to “Enjoy NixOS”">​</a></h3><p>現在，NixOS 已經帶着所有你想安裝的軟件和 KDE Plasma 5 桌面運行起來了。要知道，你所做的不僅僅只是安裝了個 Linux 發行版，關鍵是你自定義出來的發行版非常符合你的需求。所以好好享受你的 NixOS 吧！</p><hr>',17)),n("p",null,[s[18]||(s[18]=i("via: ",-1)),t(e,{href:"https://www.linux.com/learn/intro-to-linux/2017/10/nixos-linux-lets-you-configure-your-os-installing"},{default:a(()=>[...s[17]||(s[17]=[i("https://www.linux.com/learn/intro-to-linux/2017/10/nixos-linux-lets-you-configure-your-os-installing",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=i("作者：",-1)),t(e,{href:"https://www.linux.com/users/jlwallen"},{default:a(()=>[...s[19]||(s[19]=[i("JACK WALLEN",-1)])]),_:1}),s[23]||(s[23]=i(" 譯者：",-1)),t(e,{href:"https://github.com/martin2011qi"},{default:a(()=>[...s[20]||(s[20]=[i("martin2011qi",-1)])]),_:1}),s[24]||(s[24]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[21]||(s[21]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[27]||(s[27]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[25]||(s[25]=[i("LCTT",-1)])]),_:1}),s[28]||(s[28]=i(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[26]||(s[26]=[i("Linux中國",-1)])]),_:1}),s[29]||(s[29]=i(" 榮譽推出",-1))])])}const L=o(u,[["render",g]]);export{y as __pageData,L as default};
